import { useMemo } from "react";
import type { ComponentMetadata } from "../../types";
import { processPropsJSON } from "../../utils/processPropsJSON";
import { Box } from "../Box";
import { DocsSection } from "../DocsSection";
import { Header } from "../Header";
import { ComponentPropsSection } from "./ComponentPropsSection";

/**
 * Documentation for a component's props, generated by `compileDocs` from their TSDoc comments.
 * Props are split into required and optional lists, and each is included in the "On this page" contents.
 */
export function ComponentProps({
  json,
  section
}: {
  /** JSON generated by `compileDocs` (e.g. `public/generated/docs/List.json`) */
  json: ComponentMetadata;
  /** Label shown above the page title */
  section: string;
}) {
  const { optionalProps, requiredProps } = useMemo(
    () => processPropsJSON(json),
    [json]
  );

  return (
    <Box direction="column" gap={4}>
      <Header
        section={section}
        sourceCodePath={json.filePath}
        title={`${json.name} component props`}
      />
      <DocsSection sections={json.description} />
      <ComponentPropsSection header="Required props" props={requiredProps} />
      <ComponentPropsSection header="Optional props" props={optionalProps} />
    </Box>
  );
}
